<div class='card'>
  <div class='card-title'>🍎 Princípios de Alimentação</div>
  <div style='font-size: 13px; color: var(--text-muted); line-height: 1.6;'>
    
    <h4 style='color: var(--primary); margin: 15px 0 5px;'>1. Densidade Nutricional</h4>
    <p>Priorize alimentos que fornecem mais vitaminas, minerais e proteínas por caloria. Isso ajuda a atingir suas necessidades nutricionais sem exceder o consumo calórico.</p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li><strong>Alta densidade:</strong> Ovos, fígado, peixes gordurosos, folhas verde-escuras, leguminosas, frutas inteiras, tubérculos.</li>
      <li><strong>Baixa densidade:</strong> Refrigerantes, salgadinhos, doces industrializados, pães brancos, frituras em óleo reutilizado.</li>
    </ul>
    <p><strong>Dica prática:</strong> Se o alimento tem lista de ingredientes com mais de 5 itens ou nomes que você não reconhece, provavelmente é ultraprocessado.</p>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>2. Cálculo de Necessidades Calóricas</h4>
    <p>Estimativa do gasto energético diário (TDEE):</p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li><strong>Taxa Metabólica Basal (TMB) - Fórmula Mifflin-St Jeor:</strong></li>
      <li>Homens: (10 &#215; peso kg) + (6.25 &#215; altura cm) &#8722; (5 &#215; idade) + 5</li>
      <li>Mulheres: (10 &#215; peso kg) + (6.25 &#215; altura cm) &#8722; (5 &#215; idade) &#8722; 161</li>
      <li><strong>Multiplicadores de atividade:</strong></li>
      <li>Sedentário (escritório, sem exercício): TMB &#215; 1.2</li>
      <li>Levemente ativo (1-3 treinos/semana): TMB &#215; 1.375</li>
      <li>Moderadamente ativo (3-5 treinos/semana): TMB &#215; 1.55</li>
      <li>Muito ativo (6-7 treinos/semana): TMB &#215; 1.725</li>
      <li>Atleta (2x por dia ou trabalho físico pesado): TMB &#215; 1.9</li>
    </ul>
    <p><strong>Ajustes:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Perda de gordura: TDEE &#8722; 300 a 500 kcal (déficit moderado)</li>
      <li>Ganho muscular: TDEE + 200 a 300 kcal (superávit controlado)</li>
      <li>Manutenção/recomposição: comer no TDEE com proteína alta</li>
    </ul>
    <p><strong>Importante:</strong> Fórmulas são estimativas. Ajuste com base no resultado real após 2-3 semanas. Peso estável = manutenção encontrada.</p>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>3. Macronutrientes: Funções e Proporções</h4>
    <p>O balanço calórico determina ganho ou perda de peso. A distribuição de macros influencia a composição corporal.</p>
    
    <p><strong>Proteínas (4 kcal/g):</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Meta: 1.6g a 2.2g por kg de peso corporal para quem treina</li>
      <li>Em déficit calórico: aumentar para 2.0-2.4g/kg para preservar músculo</li>
      <li>Maior efeito térmico (~25% das calorias gastas na digestão)</li>
      <li>Maior saciedade entre os macronutrientes</li>
      <li>Distribuir em 3-5 refeições (20-40g por refeição é o ideal para síntese proteica)</li>
      <li><strong>Fontes completas:</strong> carnes, ovos, laticínios, peixes, whey</li>
      <li><strong>Fontes vegetais:</strong> combinar leguminosas + cereais (feijão + arroz, lentilha + quinoa)</li>
    </ul>
    
    <p><strong>Gorduras (9 kcal/g):</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Mínimo: 0.5g por kg (abaixo disso afeta hormônios)</li>
      <li>Ideal: 0.8g a 1.2g por kg</li>
      <li>Essenciais para absorção de vitaminas A, D, E, K</li>
      <li>Base para produção de testosterona, estrogênio, cortisol</li>
      <li><strong>Priorizar:</strong> azeite extra-virgem, abacate, oleaginosas, peixes gordurosos, gema de ovo</li>
      <li><strong>Limitar:</strong> óleos vegetais refinados (soja, milho, canola), gordura trans, frituras</li>
      <li><strong>Proporção ômega-6/ômega-3:</strong> ideal abaixo de 4:1 (a maioria das pessoas está em 15:1 ou mais)</li>
    </ul>
    
    <p><strong>Carboidratos (4 kcal/g):</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Quantidade: o que sobrar após definir proteína e gordura</li>
      <li>Principal substrato para exercícios de alta intensidade (musculação, HIIT, esportes)</li>
      <li>Não são &quot;essenciais&quot; tecnicamente, mas são práticos e úteis para performance</li>
      <li><strong>Fontes preferíveis:</strong> arroz, batata, batata-doce, mandioca, aveia, frutas</li>
      <li><strong>Limitar:</strong> açúcar refinado, farinhas brancas, sucos de caixa</li>
      <li>Índice glicêmico importa menos do que o contexto da refeição (combinado com proteína e fibra, a absorção é mais lenta)</li>
    </ul>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>4. Timing de Nutrientes</h4>
    <p>O horário das refeições tem impacto menor do que o total diário, mas pode otimizar performance e recuperação:</p>
    
    <p><strong>Pré-treino (1-3h antes):</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Carboidrato moderado (0.5-1g por kg)</li>
      <li>Proteína moderada (20-30g)</li>
      <li>Baixa gordura e fibra para evitar desconforto gástrico</li>
      <li>Exemplo: arroz + frango, pão + ovos, banana + whey</li>
    </ul>
    
    <p><strong>Durante o treino:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Treinos até 90 min: água é suficiente</li>
      <li>Treinos acima de 90 min ou em jejum: 30-60g de carboidrato simples podem ajudar</li>
      <li>Atletas de endurance: bebida isotônica ou maltodextrina</li>
    </ul>
    
    <p><strong>Pós-treino (até 2-3h depois):</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Proteína de rápida absorção (20-40g): whey, ovos, frango</li>
      <li>Carboidrato para repor glicogênio: a quantidade depende da intensidade do treino</li>
      <li>A janela anabólica é mais longa do que se pensava &#8212; não precisa correr para tomar shake</li>
      <li>Se você fez uma refeição pré-treino, a urgência é ainda menor</li>
    </ul>
    
    <p><strong>Antes de dormir:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Evitar refeições muito volumosas (pode atrapalhar qualidade do sono)</li>
      <li>Proteína de digestão lenta pode ser útil: queijo cottage, caseína, iogurte grego</li>
      <li>Carboidratos à noite não engordam mais do que em outros horários (mito)</li>
    </ul>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>5. Ciclagem de Carboidratos</h4>
    <p>Estratégia opcional para otimizar composição corporal:</p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li><strong>Dias de treino intenso (perna, costas, peito):</strong> 3-5g de carboidrato por kg</li>
      <li><strong>Dias de treino moderado (braços, ombros):</strong> 2-3g por kg</li>
      <li><strong>Dias de descanso:</strong> 1-2g por kg, aumentando gorduras para compensar calorias</li>
    </ul>
    <p><strong>Nota:</strong> Isso não é obrigatório e adiciona complexidade. O total semanal importa mais que a distribuição diária para a maioria das pessoas. Use apenas se você já domina o básico.</p>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>6. Recuperação e Síntese Proteica</h4>
    <p>Após o exercício, a síntese proteica muscular fica elevada por 24-48 horas.</p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>A refeição pós-treino inicia o processo, mas as refeições seguintes também contam</li>
      <li>Distribuir proteína ao longo do dia é mais eficaz que concentrar em uma refeição</li>
      <li>Mínimo de 3 refeições com proteína, ideal 4-5</li>
      <li>Proteína antes de dormir pode aumentar síntese proteica noturna</li>
      <li>Suplementos não são necessários se a alimentação for adequada</li>
    </ul>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>7. Micronutrientes Relevantes</h4>
    <p>Deficiências comuns que afetam performance e saúde:</p>
    
    <p><strong>Vitamina D:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Exposição solar: 15-20 min/dia com braços e pernas expostos</li>
      <li>Suplementação: 1000-4000 UI/dia (dose depende do nível sanguíneo)</li>
      <li>Afeta: força muscular, imunidade, humor, qualidade do sono</li>
      <li>Maioria dos brasileiros é deficiente, especialmente quem trabalha em ambiente fechado</li>
      <li>Exame: 25-hidroxivitamina D. Ideal: 40-60 ng/mL</li>
    </ul>
    
    <p><strong>Magnésio:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Fontes: folhas verdes escuras, sementes de abóbora, chocolate amargo 70%+, abacate</li>
      <li>Suplementação: 200-400mg/dia (glicinato ou bisglicinato são melhor absorvidos)</li>
      <li>Afeta: qualidade do sono, recuperação muscular, controle de cãibras</li>
      <li>Tomar à noite pode melhorar o sono</li>
    </ul>
    
    <p><strong>Zinco:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Fontes: carnes vermelhas, ostras, sementes de abóbora, castanha de caju</li>
      <li>Afeta: produção de testosterona, imunidade, cicatrização</li>
      <li>Suplementação: 15-30mg/dia (não exceder 40mg &#8212; excesso é tóxico)</li>
      <li>Competição com cobre: suplementação prolongada pode causar deficiência de cobre</li>
    </ul>
    
    <p><strong>Ferro:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Fontes: carnes vermelhas, vísceras (fígado), feijão preto</li>
      <li>Ferro heme (animal) é 2-3x melhor absorvido que não-heme (vegetal)</li>
      <li>Vitamina C aumenta absorção do ferro não-heme</li>
      <li>Café e chá reduzem absorção &#8212; evitar junto com refeições ricas em ferro</li>
      <li>Grupos de risco: mulheres em idade fértil, vegetarianos, atletas de endurance</li>
      <li>Não suplementar sem exame &#8212; excesso de ferro é perigoso</li>
    </ul>
    
    <p><strong>Ômega-3 (EPA/DHA):</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Fontes: salmão, sardinha, cavala, arenque (2-3 porções por semana)</li>
      <li>Suplementação: 1-3g de EPA+DHA combinados por dia</li>
      <li>Afeta: inflamação, recuperação, saúde cardiovascular, função cerebral</li>
      <li>Óleo de linhaça não substitui &#8212; conversão de ALA para EPA/DHA é muito baixa (~5%)</li>
    </ul>
    
    <p><strong>Vitamina B12:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Fontes: exclusivamente animais (carnes, ovos, laticínios)</li>
      <li>Vegetarianos e veganos: suplementação é obrigatória</li>
      <li>Suplementação: 250-1000mcg/dia ou 2500mcg/semana</li>
      <li>Deficiência causa: fadiga, anemia, danos neurológicos</li>
    </ul>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>8. Hidratação</h4>
    <p>Desidratação de 2% do peso corporal já reduz performance física e cognitiva.</p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li><strong>Meta base:</strong> 35ml por kg de peso corporal (70kg = ~2.5L/dia)</li>
      <li><strong>Ajustes:</strong> +500ml a 1L em dias de treino ou calor intenso</li>
      <li><strong>Indicador:</strong> Urina amarelo-clara indica hidratação adequada</li>
      <li><strong>Eletrólitos:</strong> Se suar muito, adicione pitada de sal na água ou consuma água de coco</li>
      <li>Café e chá contam para hidratação (efeito diurético é leve)</li>
      <li>Beber água em excesso também é problema &#8212; pode diluir eletrólitos (hiponatremia)</li>
    </ul>
    
    <p><strong>Sinais de desidratação:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Urina escura</li>
      <li>Dor de cabeça</li>
      <li>Fadiga desproporcional</li>
      <li>Cãibras</li>
      <li>Queda de performance no treino</li>
    </ul>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>9. Saúde Intestinal</h4>
    <p>A absorção de nutrientes depende da integridade do trato digestivo.</p>
    
    <p><strong>Fibras:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Meta: 25-35g/dia de fontes variadas</li>
      <li>Solúveis (aveia, leguminosas, frutas): alimentam bactérias benéficas</li>
      <li>Insolúveis (vegetais, grãos integrais): melhoram trânsito intestinal</li>
      <li>Aumentar gradualmente &#8212; aumento brusco causa gases e desconforto</li>
    </ul>
    
    <p><strong>Probióticos e prebióticos:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Probióticos (bactérias): iogurte natural, kefir, chucrute, kimchi, kombucha</li>
      <li>Prebióticos (alimento das bactérias): alho, cebola, banana verde, aveia, aspargos</li>
      <li>Suplementos probióticos: evidência mista &#8212; alimentos fermentados são preferíveis</li>
    </ul>
    
    <p><strong>Sinais de problemas:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Inchaço frequente após refeições</li>
      <li>Gases excessivos</li>
      <li>Alternância entre diarreia e constipação</li>
      <li>Fadiga crônica mesmo com alimentação adequada</li>
      <li>Se persistir, investigar: SIBO, intolerâncias, síndrome do intestino irritável</li>
    </ul>
    
    <p><strong>Hábitos que ajudam:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Mastigar bem (20-30 mastigações por garfada)</li>
      <li>Não beber líquidos em excesso durante refeições</li>
      <li>Comer sem distrações (TV, celular)</li>
      <li>Identificar e eliminar alimentos gatilho</li>
    </ul>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>10. Jejum Intermitente</h4>
    <p>Estratégia de restrição de janela alimentar. O que a ciência mostra:</p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li><strong>Para perda de peso:</strong> não é superior a déficit calórico convencional quando as calorias são iguais</li>
      <li><strong>Vantagem:</strong> algumas pessoas acham mais fácil controlar calorias com menos refeições</li>
      <li><strong>Desvantagem:</strong> pode dificultar atingir meta de proteína, especialmente se for alta</li>
      <li><strong>Protocolos comuns:</strong> 16:8 (16h jejum, 8h alimentação), 18:6, 20:4, OMAD (uma refeição)</li>
      <li><strong>Quem deve evitar:</strong> pessoas com histórico de transtorno alimentar, diabéticos sem acompanhamento, gestantes, adolescentes</li>
      <li><strong>Benefícios metabólicos:</strong> existem, mas são modestos e podem ser obtidos com outras estratégias</li>
    </ul>
    <p><strong>Conclusão:</strong> É uma ferramenta, não mágica. Use se funcionar para seu estilo de vida.</p>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>11. Álcool</h4>
    <p>Impacto real no corpo e nos resultados:</p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li><strong>Calorias:</strong> 7 kcal/g (quase o dobro de carboidratos e proteínas)</li>
      <li><strong>Prioridade metabólica:</strong> corpo para tudo para metabolizar o álcool primeiro &#8212; gordura e carboidrato vão para estoque</li>
      <li><strong>Síntese proteica:</strong> reduzida em até 24-37% após consumo moderado a alto</li>
      <li><strong>Testosterona:</strong> redução aguda, especialmente com consumo excessivo</li>
      <li><strong>Sono:</strong> prejudica qualidade mesmo que ajude a adormecer</li>
      <li><strong>Recuperação:</strong> aumenta inflamação e desidratação</li>
    </ul>
    
    <p><strong>Se for beber:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Preferir: vinho seco, destilados puros (vodka, whisky) &#8212; menos calorias</li>
      <li>Evitar: cervejas, drinks com açúcar, coquetéis</li>
      <li>Comer proteína antes de beber</li>
      <li>Alternar drink com água</li>
      <li>Evitar beber em dias de treino pesado</li>
      <li>Limite razoável: 1-2 doses, não mais que 2x por semana</li>
    </ul>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>12. Suplementos</h4>
    <p>Ordem de prioridade (do mais para o menos útil):</p>
    
    <p><strong>Categoria A &#8212; Eficácia comprovada:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li><strong>Creatina monohidratada:</strong> 3-5g/dia, todos os dias. Aumento de força, massa muscular e performance. Um dos suplementos mais estudados e seguros.</li>
      <li><strong>Proteína em pó (whey, caseína):</strong> Conveniência para atingir meta proteica. Não é superior a comida, apenas mais prático.</li>
      <li><strong>Cafeína:</strong> 3-6mg/kg, 30-60 min antes do treino. Melhora performance e foco. Tolerância se desenvolve com uso diário.</li>
    </ul>
    
    <p><strong>Categoria B &#8212; Útil em contextos específicos:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li><strong>Vitamina D:</strong> Se não tiver exposição solar adequada ou exame mostrar deficiência.</li>
      <li><strong>Ômega-3:</strong> Se não comer peixe regularmente.</li>
      <li><strong>Magnésio:</strong> Se tiver problemas de sono ou cãibras.</li>
      <li><strong>Vitamina B12:</strong> Obrigatório para veganos.</li>
    </ul>
    
    <p><strong>Categoria C &#8212; Evidência fraca ou mínima:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>BCAAs (se você já consome proteína suficiente, são inúteis)</li>
      <li>Glutamina (não funciona para quem se alimenta bem)</li>
      <li>Termogênicos (maioria é cafeína cara com ingredientes inúteis)</li>
      <li>Pré-treinos elaborados (maioria do efeito é da cafeína)</li>
      <li>Colágeno hidrolisado (proteína de baixa qualidade)</li>
    </ul>
    
    <p><strong>Não existem atalhos:</strong> suplementos representam no máximo 5% do resultado. Os outros 95% vêm de treino, alimentação e sono.</p>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>13. Comer Fora e Situações Sociais</h4>
    <p>Estratégias para manter consistência sem se isolar:</p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Olhe o cardápio antes de ir &#8212; escolha com calma</li>
      <li>Peça proteína + vegetais + carboidrato simples (grelhado, não frito)</li>
      <li>Substitua acompanhamentos (troque batata frita por salada ou arroz)</li>
      <li>Evite molhos cremosos, empanados, frituras</li>
      <li>Peça molho à parte</li>
      <li>Não chegue com fome extrema &#8212; coma algo leve antes</li>
      <li>Uma refeição não arruína nada &#8212; o problema é a sequência de más escolhas</li>
      <li>Se for dia de &quot;liberdade&quot;, planeje: treine nesse dia, reduza calorias em outras refeições</li>
    </ul>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>14. Estratégias para Controle de Fome</h4>
    <p>Se você está em déficit calórico e sente fome:</p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li><strong>Aumente volume:</strong> vegetais folhosos, pepino, abobrinha têm poucas calorias e ocupam espaço</li>
      <li><strong>Priorize proteína:</strong> é o macro mais saciante &#8212; inclua em toda refeição</li>
      <li><strong>Fibras:</strong> aveia, leguminosas, vegetais retardam digestão</li>
      <li><strong>Líquidos:</strong> beber água antes das refeições reduz ingestão calórica</li>
      <li><strong>Sono:</strong> privação de sono aumenta grelina (hormônio da fome)</li>
      <li><strong>Coma devagar:</strong> leva 20 min para sinais de saciedade chegarem ao cérebro</li>
      <li><strong>Evite calorias líquidas:</strong> sucos, refrigerantes, cafés adoçados não saciam</li>
      <li><strong>Estruture refeições:</strong> comer em horários regulares regula hormônios da fome</li>
      <li><strong>Reduza exposição:</strong> não tenha junk food em casa &#8212; fora de vista, fora da mente</li>
    </ul>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>15. Refeições Práticas e Rápidas</h4>
    <p>Ideias para quem tem pouco tempo:</p>
    
    <p><strong>Café da manhã (alto em proteína):</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Ovos mexidos + pão integral + abacate (5 min)</li>
      <li>Iogurte grego + aveia + frutas + castanhas (2 min)</li>
      <li>Shake: whey + banana + pasta de amendoim + leite (2 min)</li>
      <li>Overnight oats: aveia + leite + whey + frutas (preparo na noite anterior)</li>
    </ul>
    
    <p><strong>Almoço/Jantar:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Frango grelhado + arroz + brócolis (pode preparar em batch)</li>
      <li>Carne moída + batata-doce + salada</li>
      <li>Omelete com legumes + pão</li>
      <li>Salmão + quinoa + vegetais assados</li>
      <li>Filé de peixe + purê de batata + espinafre</li>
    </ul>
    
    <p><strong>Lanches:</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Queijo cottage + frutas</li>
      <li>Castanhas + chocolate amargo 70%+</li>
      <li>Ovo cozido (prepare vários de uma vez)</li>
      <li>Iogurte natural + whey</li>
      <li>Banana + pasta de amendoim</li>
    </ul>
    
    <p><strong>Meal prep:</strong> Cozinhar proteínas e carboidratos para 3-4 dias no fim de semana economiza tempo durante a semana.</p>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>16. Como Ler Rótulos</h4>
    <p>O que observar:</p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li><strong>Porção:</strong> verifique se corresponde ao que você realmente consome</li>
      <li><strong>Calorias:</strong> valor por porção, não por embalagem</li>
      <li><strong>Proteína:</strong> quanto maior, geralmente melhor</li>
      <li><strong>Açúcar:</strong> quanto menor, melhor. OMS recomenda máximo 25g/dia de açúcar adicionado</li>
      <li><strong>Sódio:</strong> limite 2300mg/dia (5g de sal). Alimentos processados são os maiores vilões</li>
      <li><strong>Fibras:</strong> quanto mais, melhor para saciedade</li>
      <li><strong>Gordura trans:</strong> evitar completamente (0g é o ideal)</li>
      <li><strong>Lista de ingredientes:</strong> ordem é por quantidade. Se açúcar ou óleo vegetal estão no início, evite</li>
      <li><strong>Nomes disfarçados de açúcar:</strong> xarope de glicose, maltose, dextrose, xarope de milho, açúcar invertido</li>
    </ul>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>17. Sinais de que a Dieta Está Funcionando</h4>
    <p>Além da balança:</p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Roupas ficando mais folgadas (mesmo sem mudança no peso)</li>
      <li>Medidas diminuindo (cintura é a mais relevante)</li>
      <li>Força mantida ou aumentando no treino</li>
      <li>Energia estável ao longo do dia</li>
      <li>Sono melhorando</li>
      <li>Fome controlada entre refeições</li>
      <li>Fotos comparativas mostram diferença</li>
    </ul>
    
    <p><strong>Sinais de alerta (dieta muito agressiva):</strong></p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Perda de força significativa</li>
      <li>Fadiga constante</li>
      <li>Fome extrema o tempo todo</li>
      <li>Irritabilidade</li>
      <li>Perda de libido</li>
      <li>Alterações no ciclo menstrual (mulheres)</li>
      <li>Perda de peso muito rápida (mais de 1% do peso por semana)</li>
      <li>Queda de cabelo</li>
    </ul>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>18. Mitos Comuns</h4>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li><strong>&quot;Comer à noite engorda&quot;</strong> &#8212; Falso. O que importa é o total calórico diário.</li>
      <li><strong>&quot;Ovo aumenta colesterol&quot;</strong> &#8212; Para a maioria das pessoas, o colesterol dietético tem impacto mínimo no colesterol sanguíneo.</li>
      <li><strong>&quot;Preciso comer de 3 em 3 horas&quot;</strong> &#8212; Falso. Frequência alimentar não afeta metabolismo.</li>
      <li><strong>&quot;Whey é bomba&quot;</strong> &#8212; Whey é apenas proteína do leite em pó.</li>
      <li><strong>&quot;Carboidrato engorda&quot;</strong> &#8212; Excesso calórico engorda, não um macronutriente específico.</li>
      <li><strong>&quot;Detox/suco verde limpa o organismo&quot;</strong> &#8212; Fígado e rins fazem isso. Sucos são apenas calorias líquidas.</li>
      <li><strong>&quot;Comer gordura engorda&quot;</strong> &#8212; Gordura é calórica, mas necessária. O problema é o excesso calórico.</li>
      <li><strong>&quot;Preciso de 2g de proteína por libra (4.4g/kg)&quot;</strong> &#8212; Exagero. 1.6-2.2g/kg é suficiente.</li>
      <li><strong>&quot;Treinar em jejum queima mais gordura&quot;</strong> &#8212; O que importa é o déficit calórico de 24h, não o estado de jejum.</li>
    </ul>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>19. Sustentabilidade da Dieta</h4>
    <p>A melhor dieta é aquela que você consegue manter a longo prazo.</p>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Seguir 80-90% do planejado já produz resultados. Perfeccionismo leva a desistência.</li>
      <li>Inclua alimentos que você gosta dentro das metas calóricas e proteicas.</li>
      <li>Preparar refeições com antecedência reduz decisões impulsivas.</li>
      <li>Mudanças graduais são mais eficazes que reformulações radicais.</li>
      <li>Se errar, não compense com restrição extrema &#8212; apenas retome no próximo dia.</li>
      <li>Diet breaks: períodos curtos comendo na manutenção podem ajudar em déficits longos.</li>
    </ul>

    <h4 style='color: var(--primary); margin: 15px 0 5px;'>20. Erros Comuns a Evitar</h4>
    <ul style='padding-left: 20px; margin: 5px 0;'>
      <li>Cortar grupos alimentares inteiros sem necessidade médica</li>
      <li>Subestimar calorias líquidas (sucos, álcool, cafés adoçados)</li>
      <li>Focar em suplementos antes de acertar a alimentação básica</li>
      <li>Ignorar proteína no café da manhã</li>
      <li>Déficit calórico muito agressivo (acima de 500-700 kcal)</li>
      <li>Não pesar/medir alimentos (a maioria subestima em 30-50%)</li>
      <li>Confiar em &quot;alimentos fit&quot; (muitos são ultraprocessados disfarçados)</li>
      <li>Ignorar consistência em favor de perfeição</li>
      <li>Comparar seu progresso com pessoas em contextos diferentes</li>
      <li>Mudar de estratégia a cada semana sem dar tempo para resultados</li>
    </ul>

  </div>
</div>

